#!/bin/bash
# Uninstall script for XnSoft XnConvert
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling XnSoft XnConvert..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping XnSoft XnConvert if running..."
pkill -f "XnSoft XnConvert" 2>/dev/null || true

# Kill application with bundle ID com.xnview.XnConvert if running
echo "Stopping application with bundle ID com.xnview.XnConvert if running..."
killall -9 "com.xnview.XnConvert" 2>/dev/null || true

# Remove /Applications/XnConvert.app
echo "Removing /Applications/XnConvert.app..."
if [ -d "/Applications/XnConvert.app" ]; then
    rm -rf "/Applications/XnConvert.app" 2>/dev/null || true
elif [ -f "/Applications/XnConvert.app" ]; then
    rm -f "/Applications/XnConvert.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.xnview.XnConvert.plist
echo "Removing $HOME/Library/Preferences/com.xnview.XnConvert.plist..."
if [ -d "$HOME/Library/Preferences/com.xnview.XnConvert.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.xnview.XnConvert.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.xnview.XnConvert.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.xnview.XnConvert.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
